SELECT SUM(orders_gross_qty) AS orders_gross_qty
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(buyouts_qty) AS buyouts_qty
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(sales_revenue_seller_base_rub) AS revenue_rub
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(contribution_pre_cogs_rub) AS contribution_rub
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(ad_spend_attributed_rub) AS ad_spend_rub
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SAFE_DIVIDE(SUM(ad_spend_attributed_rub), SUM(sales_revenue_seller_base_rub)) AS drr
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(returns_qty) AS returns_qty
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(net_settlement_rub) AS net_settlement_rub
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(period_result_pre_cogs_corrected_rub) AS period_result_rub
FROM `wb_mart.V_DASH_FINANCE_CORRECTED_DAILY`
WHERE {{day}}

SELECT SUM(canceled_qty) AS canceled_qty
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

WITH f AS (
  SELECT day FROM `wb_mart.V_DASH_FINANCE_CORRECTED_DAILY`
  WHERE {{day}}
)
SELECT SUM(IF(e.after_product_cogs_eligible, e.product_cogs_rub, NULL)) AS product_cogs_rub
FROM f JOIN `wb_mart.V_DASH_EXECUTIVE_ECONOMICS_DAILY` e USING (day)

WITH f AS (
  SELECT day FROM `wb_mart.V_DASH_FINANCE_CORRECTED_DAILY`
  WHERE {{day}}
)
SELECT SUM(e.period_result_after_product_cogs_rub) AS period_result_after_cogs_rub
FROM f JOIN `wb_mart.V_DASH_EXECUTIVE_ECONOMICS_DAILY` e USING (day)
